import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is linkwarden-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788283445000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-linkwarden-mcp" tabindex="-1">What is linkwarden-mcp? <a class="header-anchor" href="#what-is-linkwarden-mcp" aria-label="Permalink to “What is linkwarden-mcp?”">​</a></h1><p><a href="https://linkwarden.app" target="_blank" rel="noreferrer">Linkwarden</a> is a self-hosted bookmark manager whose defining feature is that it does not just store a URL: when you save a page, it keeps a copy — as readable article text, as a PDF, as a screenshot, and as a single-file HTML archive. Your bookmarks survive the pages they point at.</p><p><code>linkwarden-mcp</code> is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server that puts that collection in reach of an assistant. It exposes 28 tools over stdio: 11 that read and 17 that write.</p><h2 id="what-it-is-good-at" tabindex="-1">What it is good at <a class="header-anchor" href="#what-it-is-good-at" aria-label="Permalink to “What it is good at”">​</a></h2><p><strong>Answering from what you already saved.</strong> <code>get_link_content</code> returns the article text Linkwarden extracted when it preserved the page. An assistant can summarise, compare or quote a bookmark from months ago without going back to the live web — which matters most exactly when the original has changed, moved behind a paywall, or disappeared.</p><p><strong>Keeping the collection tidy.</strong> Creating links, moving them between collections, renaming and merging tags, bulk-tagging a batch of search results.</p><p><strong>Not being a foot-gun.</strong> The parts that are easy to get wrong are handled explicitly: partial updates merge rather than replace, output is an allowlist rather than a dump of Linkwarden&#39;s database rows, and anything destructive <a href="/guide/approval">asks a person</a> — bound to the exact target.</p><h2 id="what-it-deliberately-does-not-do" tabindex="-1">What it deliberately does not do <a class="header-anchor" href="#what-it-deliberately-does-not-do" aria-label="Permalink to “What it deliberately does not do”">​</a></h2><ul><li><strong>Access-token management.</strong> A tool that can mint API credentials is a privilege-escalation surface.</li><li><strong>User administration</strong>, including account deletion.</li><li><strong>Backup export and import.</strong> The export dumps the whole instance into the model&#39;s context; the import can destroy it.</li><li><strong>Highlights.</strong> Creating one needs exact character offsets into the preserved document, which a model cannot produce meaningfully, and Linkwarden has no route to list existing ones.</li><li><strong>Archive uploads</strong> and the signed <code>preserved</code> URLs, which need <code>NEXT_PUBLIC_USER_CONTENT_DOMAIN</code> configured.</li></ul><h2 id="a-note-on-the-source-of-truth" tabindex="-1">A note on the source of truth <a class="header-anchor" href="#a-note-on-the-source-of-truth" aria-label="Permalink to “A note on the source of truth”">​</a></h2><p>Linkwarden&#39;s published API reference is incomplete. This server was written against the routes in <code>apps/web/pages/api/v1/**</code> and the request schemas in <code>packages/lib/schemaValidation.ts</code> of <a href="https://github.com/linkwarden/linkwarden" target="_blank" rel="noreferrer">linkwarden/linkwarden</a>, verified against <strong>v2.16.0</strong>. Where the two disagree, the code wins — and the surprises that came out of that reading are documented in <a href="/guide/security">Security</a> and the <a href="/guide/faq">FAQ</a>, because they change what a caller should expect.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — token, install, first call</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/reference/tools">Tool reference</a> — all 28 tools</li></ul>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};